const std::regex R(R"(\b(\w+)\b)"); // Pre-compiled structure
const std::string Input = "a b c";
const std::string Format = "$1_REP";

std::string Output;
// Compiler optimization targets: minimize reallocations.
// Internal heuristic: Output.reserve(Input.size() * Factor);

// Iterator-based overload efficiency
auto end_it = std::regex_replace(
    std::back_inserter(Output), // Avoids intermediate result copies
    Input.cbegin(), Input.cend(),
    R, Format,
    std::regex_constants::format_default
);

// If no matches: Avoids O(N) allocation/copy by checking match_results.empty()
// Match handling uses std::sub_match iterators (no string construction until output).
